/* Guarded administration forms. Server RPCs validate every value and permission. */
window.MioMemberManagement=(()=>{
 const labels={account:'Package, rank & status',wallets:'Wallet balances',earnings:'Opening earnings',maintenance:'Maintenance countdowns',points:'Network points',placement:'Sponsor & binary placement'};
 const fields={wallets:{cash:'Cash Wallet · MIO',proceed:'Proceed Wallet · MIO',shopping:'Shopping Points',promotion:'Promotion Points',exchange:'Exchange Wallet · MIO'},earnings:{direct:'Direct bonus',generation:'Generation bonus',binary_pool_share:'Binary bonus',manager:'Manager bonus',community_share:'Community Share bonus',single_line:'Binary Placement / Single Line bonus',ecommerce:'E-commerce income',other:'Other income'},points:{ppv:'Personal PPV',bv:'Personal BV',gp:'Personal GP',dp:'Personal DP',direct_points:'Working Direct Points',tngp:'Total Network Generation Points',bp_left:'Lifetime Left BP',bp_right:'Lifetime Right BP',carry_left:'Remaining Left BP',carry_right:'Remaining Right BP',brp_left:'Left Binary Rank Points',brp_right:'Right Binary Rank Points',left_dp:'Left Direct Points',right_dp:'Right Direct Points',left_gp:'Left Generation Points',right_gp:'Right Generation Points'},maintenance:{monthly_days:'Monthly maintenance · days remaining',annual_days:'Annual maintenance · days remaining',monthly_progress_ppv:'Monthly maintenance PPV progress'}};
 function shell(api,title){const dialog=document.createElement('dialog');dialog.className='member-management-dialog';dialog.innerHTML=`<header><h2>${api.esc(title)}</h2><button type="button" data-close aria-label="Close">×</button></header><div data-management-body><p>Loading current values…</p></div>`;api.root.append(dialog);dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();return dialog;}
 const key=()=>crypto.randomUUID();
 function controls(){return `<details class="member-management-controls"><summary>Edit this member’s account</summary><div>${Object.entries(labels).map(([k,v])=>`<button type="button" class="btn small" data-manage-section="${k}">${v}</button>`).join('')}</div></details>`;}
 async function edit(api,member,section,refresh){if(!api.authorized()||!labels[section])return;const owner=api.identity(),dialog=shell(api,labels[section]),alive=()=>dialog.isConnected&&api.authorized()&&api.identity()===owner;const host=dialog.querySelector('[data-management-body]');try{
  const {data,error}=await api.db.rpc('admin_member_management',{p_member:member.user_id});if(!alive())return;if(error)throw error;const original=data.state[section],esc=api.esc;let values={...original},html='';
  const select=(name,label,options,value)=>`<label>${esc(label)}<select name="${name}">${options.map(([k,v])=>`<option value="${esc(k)}" ${String(value??'')===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;
  if(section==='account')html=select('package_code','Membership package',[['','Free'],...(data.plans||[]).map(p=>[p.code,p.name])],values.package_code)+select('rank','Leadership rank',[['','Unranked'],...(data.ranks||[]).map(r=>[r.code,r.name])],values.rank)+select('status','Account status',[['active','Active'],['inactive','Inactive'],['suspended','Suspended']],values.status);
  if(section==='placement')html=`<label>Sponsor MIO ID<input name="sponsor_code" required value="${esc(values.sponsor_code||'')}"></label><label>Placement MIO ID<input name="placement_code" required value="${esc(values.placement_code||'')}"></label>`+select('side','Left / Right',[['LEFT','Left'],['RIGHT','Right']],values.side);
  if(section==='maintenance'){const now=new Date(data.server_now).getTime();values={monthly_days:Math.max(0,Math.ceil((new Date(values.monthly_due_at).getTime()-now)/86400000)||0),annual_days:Math.max(0,Math.ceil((new Date(values.annual_due_at).getTime()-now)/86400000)||0),monthly_progress_ppv:values.monthly_progress_ppv||0};}
  if(fields[section])html=Object.entries(fields[section]).map(([name,label])=>`<label>${esc(label)}<input type="number" name="${name}" required min="0" max="${section==='maintenance'?36500:1000000000}" step="${name.endsWith('_days')?'1':'0.0001'}" value="${esc(String(values[name]||0))}"></label>`).join('');
  const note={earnings:'Enter the old system’s earned totals by category. These values form an opening statement and do not credit any wallet. New earnings are added automatically.',wallets:'These are actual available balances. Enter the final balance required in each wallet.',account:'Restore membership and rank without purchase charges, activation bonuses or promotion-wallet release.',maintenance:'Days are counted from the time you save. Unchanged countdowns keep their existing deadline.',points:'Shopping Points are edited under Wallet balances. Carry-forward BP must not exceed lifetime BP.',placement:'Sponsor and binary placement are separate. Moving a branch retains its existing descendants and recorded points.'}[section];
  host.innerHTML=`<p>${esc(member.full_name)} · ${esc(member.member_code)}</p><p class="note">${note}</p><form class="member-state-form"><div class="management-fields">${html}</div>${section==='earnings'?'<p class="opening-total" data-opening-total></p>':''}<label>Reason for change<textarea name="reason" required minlength="10" maxlength="2000"></textarea></label><p role="status" data-status></p><button class="btn primary" type="submit">Verify & save changes</button></form>`;
  const form=host.querySelector('form'),status=host.querySelector('[data-status]');let busy=false,requestKey=key(),lastPayload=null;
  const total=()=>{const out=host.querySelector('[data-opening-total]');if(out)out.textContent='Opening total: '+Object.keys(fields.earnings).reduce((s,k)=>s+Number(form.elements[k].value||0),0).toLocaleString('en-US',{maximumFractionDigits:4})+' MIO';};form.addEventListener('input',total);total();
  form.addEventListener('submit',async e=>{e.preventDefault();e.stopPropagation();if(busy||!alive()||!form.reportValidity())return;busy=true;const button=form.querySelector('[type=submit]');button.disabled=true;try{
   const payload={};for(const name of Object.keys(values)){const input=form.elements[name];if(!input)continue;let value=input.type==='number'?Number(input.value):input.value;if(section==='account'&&name!=='status'&&value==='')value=null;if(value!==values[name])payload[name]=value;}
   if(!Object.keys(payload).length){status.textContent='No values changed.';return;}
   const reason=form.elements.reason.value.trim(),signature=JSON.stringify([payload,reason]);if(lastPayload&&signature!==lastPayload)requestKey=key();lastPayload=signature;
   await api.confirmSensitive('Save '+labels[section]+' for '+member.member_code);if(!alive())return;
   const saved=await api.db.rpc('admin_save_member_state',{p_member:member.user_id,p_section:section,p_values:payload,p_expected:original,p_key:requestKey,p_reason:reason});if(saved.error)throw saved.error;if(!alive())return;dialog.close();await refresh();
  }catch(error){if(alive())status.textContent='Could not save: '+error.message;}finally{busy=false;button.disabled=false;}});
 }catch(error){if(alive())host.textContent='Could not load edit controls: '+error.message;}}
 function createForm(api,member,placement,side,refresh){if(!api.authorized())return;const owner=api.identity(),dialog=shell(api,'Create free account'),esc=api.esc,host=dialog.querySelector('[data-management-body]'),alive=()=>dialog.isConnected&&api.authorized()&&api.identity()===owner;
 host.innerHTML=`<p>Create a member at the selected binary position. The member uses their own email to set a password and accept the terms.</p><form><div class="management-fields"><label>Full name<input name="full_name" required minlength="2" maxlength="150"></label><label>Email<input type="email" name="email" required maxlength="254"></label><label>Phone<input name="phone" required minlength="5" maxlength="40"></label><label>Country<select name="country">${api.countryOptions('PK')}</select></label><label>Gender<select name="gender"><option value="male">Male</option><option value="female">Female</option></select></label><label>Sponsor MIO ID<input name="sponsor_code" value="${esc(member.member_code)}" required></label><label>Placement MIO ID<input name="placement_code" value="${esc(placement)}" required></label><label>Left / Right<select name="side"><option value="LEFT" ${side==='LEFT'?'selected':''}>Left</option><option value="RIGHT" ${side==='RIGHT'?'selected':''}>Right</option></select></label></div><label>Reason<textarea name="reason" required minlength="10" maxlength="2000"></textarea></label><label class="setup-email-option"><input type="checkbox" name="send_setup_email">Send password setup email to this member</label><p role="status" data-status></p><button class="btn primary">Verify & create free account</button></form>`;
 const form=host.querySelector('form'),status=host.querySelector('[data-status]');let busy=false,requestKey=key(),lastDetails=null;
 form.addEventListener('submit',async e=>{e.preventDefault();e.stopPropagation();if(busy||!alive()||!form.reportValidity())return;busy=true;const button=form.querySelector('button');button.disabled=true;try{const details={};for(const name of ['full_name','email','phone','country','gender','sponsor_code','placement_code','side'])details[name]=form.elements[name].value.trim();const reason=form.elements.reason.value.trim(),sig=JSON.stringify([details,reason]);if(lastDetails&&lastDetails!==sig)requestKey=key();lastDetails=sig;await api.confirmSensitive('Create free member '+details.email+' at '+details.placement_code+' '+details.side);if(!alive())return;
 const response=await api.db.functions.invoke('admin-create-member',{body:{key:requestKey,details,reason,send_setup_email:form.elements.send_setup_email.checked}});if(response.error){let message=response.error.message;try{message=(await response.error.context.json()).error||message;}catch{}throw Error(message);}if(response.data?.error)throw Error(response.data.error);if(!alive())return;
 host.innerHTML=`<p role="status">Free account created successfully.</p><p>${esc(details.email)}</p><p>${response.data.email_status==='sent'?'Password setup email sent.':response.data.email_status==='failed'?'Account created, but email delivery failed. The member can use Forgot password on the sign-in page.':'The member can use Forgot password on the sign-in page to set their own password.'}</p><button type="button" class="btn primary" data-done>Done</button>`;host.querySelector('[data-done]').onclick=async()=>{dialog.close();await refresh?.();api.onSaved?.();};
 }catch(error){if(alive())status.textContent='Could not create: '+error.message;}finally{busy=false;button.disabled=false;}});
 }
 function editSelf(api,profile,refresh){const dialog=shell(api,'Edit my profile'),host=dialog.querySelector('[data-management-body]'),owner=api.identity(),esc=api.esc;host.innerHTML=`<form><div class="management-fields"><label>Full name<input name="full_name" required minlength="2" maxlength="150" value="${esc(profile.full_name)}"></label><label>Phone<input name="phone" required minlength="5" maxlength="40" value="${esc(profile.phone||'')}"></label><label>Country<select name="country">${api.countryOptions(profile.country_code)}</select></label><label>Gender<select name="gender" required><option value="male">Male</option><option value="female">Female</option></select></label><label>Date of birth<input type="date" name="dob" min="1900-01-01" max="${new Date().toISOString().slice(0,10)}" value="${esc(profile.date_of_birth||'')}"></label></div><p role="status" data-status></p><button class="btn primary">Save profile</button></form>`;const form=host.querySelector('form');form.elements.gender.value=profile.gender||'male';let busy=false;form.addEventListener('submit',async e=>{e.preventDefault();e.stopPropagation();if(busy||!dialog.isConnected||!api.authorized()||api.identity()!==owner||!form.reportValidity())return;busy=true;form.querySelector('button').disabled=true;try{const {error}=await api.db.rpc('save_my_profile',{p_name:form.elements.full_name.value.trim(),p_phone:form.elements.phone.value.trim(),p_country:form.elements.country.value,p_gender:form.elements.gender.value,p_dob:form.elements.dob.value||null});if(error)throw error;if(api.identity()!==owner||!dialog.isConnected)return;dialog.close();await refresh();}catch(error){host.querySelector('[data-status]').textContent=error.message;}finally{busy=false;form.querySelector('button').disabled=false;}});}
 return {controls,edit,createForm,editSelf};
})();
